import { Component, Element, Event, EventEmitter, h, Host, Prop, State } from '@stencil/core';
import { Slot, Slots, Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { Consume } from '@src/framework/runtime-context';
import { RadioGroupContext, RadioGroupContextValue } from '../ks-radio/context';
import { CheckboxGroupContext, CheckboxGroupContextValue } from '../ks-checkbox-group/context';
import { RadioValue } from '../ks-radio/types';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { FormContextValueReconcile } from '@src/components/ks-form/utils';
import type { TileOrientation, TileSelect } from './types';

const prefix = 'tile';

/**
 * @slot default - Main content rendered inside the tile body.
 * @slot title - Slot for the title content. Overrides the `title` prop.
 * @slot extra - Slot for extra content displayed in the header.
 * @slot icon - Slot for the icon area.
 * @slot footer - Slot for footer content.
 * @part base - The base container of the component.
 * @part head - The head area of the component.
 * @part body - The body content area of the component.
 * @part footer - The footer area of the component.
 */
@Component({
  tag: 'ks-tile',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsTile extends FormBaseComponent<boolean> {
  // eslint-disable-next-line @stencil-community/element-type
  @Element() el!: HTMLElement;

  @Consume({
    context: RadioGroupContext,
    subscribe: true,
  })
  @State()
  radioGroupContext?: RadioGroupContextValue;

  @Consume({
    context: CheckboxGroupContext,
    subscribe: true,
  })
  @State()
  checkboxGroupContext?: CheckboxGroupContextValue;

  /** Determines the selection control displayed by the tile. */
  @Prop() select: TileSelect = 'none';
  /** The layout orientation of the tile. */
  @Prop() orientation: TileOrientation = 'horizontal';
  /** The value used when the tile participates in a selection group. */
  @Prop() @Vue2ValueFix() value?: string | number;
  /** Title text rendered when the `title` slot is not provided. */
  @Prop() title = '';
  /** Controls the selected state of the tile. */
  @Prop() @FormContextValueReconcile({ contextKey: 'valueFromContext' }) checked?: boolean;
  /** Controls the default selected state of the tile. */
  @Prop() defaultChecked?: boolean;
  /** Whether the tile is disabled. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;

  @Slot({ slotname: 'title' }) private titleSlot?: Slots;
  @Slot({ slotname: 'extra' }) private extraSlot?: Slots;
  @Slot({ slotname: 'icon' }) private iconSlot?: Slots;
  @Slot({ slotname: 'footer' }) private footerSlot?: Slots;

  @Uncontrollable('checked', 'defaultChecked', 'ksChange') @State() private _checked?: boolean;

  /** Triggered when the tile checked state changes. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<boolean>;

  constructor() {
    super();
    registerPluginManager(this.el);
  }

  private get resolvedDisabled() {
    if (this.select === 'radio' && this.radioGroupContext?.disabled) return true;
    if (this.select === 'checkbox' && this.checkboxGroupContext?.disabled) return true;
    return this.disabled;
  }

  private get isChecked() {
    if (this.select === 'radio' && this.value !== undefined && this.radioGroupContext?.value !== undefined) {
      return this.radioGroupContext.value === this.value;
    }
    if (this.select === 'checkbox' && this.value !== undefined && this.checkboxGroupContext?.value !== undefined) {
      return this.checkboxGroupContext.value.includes(this.value);
    }
    return Boolean(this._checked);
  }

  private handleValueChange = (event: Partial<Event> & { detail: boolean }) => {
    this.ksChange.emit(event.detail);
    const hasGroupContext =
      this.select === 'radio' ? this.radioGroupContext !== undefined : this.checkboxGroupContext !== undefined;
    if (this.checked === undefined && !hasGroupContext) {
      this._checked = event.detail;
    }
  };

  private renderSelectBox() {
    if (this.select === 'none') return null;

    const selectControl =
      this.select === 'checkbox' ? (
        <ks-checkbox
          onKsChange={this.handleValueChange}
          value={this.value}
          checked={this.isChecked}
          disabled={this.resolvedDisabled}
          data-testid="ks-tile-index-checkbox"
        />
      ) : (
        <ks-radio
          onKsChange={this.handleValueChange}
          value={this.value}
          checked={this.isChecked}
          disabled={this.resolvedDisabled}
          data-testid="ks-tile-index-radio"
        />
      );

    return <div class={`${prefix}__select`}>{selectControl}</div>;
  }

  private handleClick = (event: MouseEvent) => {
    const target = event.target as HTMLElement;
    if (this.resolvedDisabled || target.closest('ks-checkbox, ks-radio')) {
      return;
    }

    if (this.select === 'radio') {
      if (this.isChecked) return;
      this.radioGroupContext?.onValueChange?.(this.value as RadioValue);
    } else if (this.select === 'checkbox') {
      this.checkboxGroupContext?.onValueChange(this.value as string | number);
    } else {
      return;
    }

    const detail = this.select === 'checkbox' ? !this.isChecked : true;
    this.handleValueChange({ detail });
  };

  componentWillLoad() {
    // handled by Uncontrollable
  }

  render() {
    return (
      <Host class="KsTile">
        <div
          class={{
            [prefix]: true,
            [`${prefix}--${this.orientation}`]: true,
            [`${prefix}--checked`]: this.select !== 'none' && this.isChecked,
            [`${prefix}--selectable`]: this.select !== 'none',
            [`${prefix}--disabled`]: Boolean(this.resolvedDisabled),
          }}
          part="base"
          onClick={this.handleClick}
          data-testid="ks-tile-index-base"
        >
          {this.orientation === 'vertical' && (
            <div class={`${prefix}__icon-row`}>
              <div class={`${prefix}__icon`}>{this.iconSlot && <slot name="icon"></slot>}</div>
              {this.renderSelectBox()}
            </div>
          )}

          <div class={`${prefix}__container`}>
            <div class={`${prefix}__head`} part="head">
              <div class={`${prefix}__head-main`}>
                {(this.iconSlot || this.titleSlot || this.title || this.extraSlot) && (
                  <div class={`${prefix}__head-title`}>
                    {this.iconSlot && this.orientation === 'horizontal' && <slot name="icon"></slot>}
                    {(this.titleSlot || this.title) && (
                      <slot name="title">
                        <span class={`${prefix}__title`}>{this.title}</span>
                      </slot>
                    )}
                    {this.extraSlot && <slot name="extra"></slot>}
                  </div>
                )}
              </div>
              {this.orientation === 'horizontal' && this.renderSelectBox()}
            </div>

            <div class={`${prefix}__body`} part="body">
              <slot></slot>
            </div>

            {this.footerSlot && (
              <div class={`${prefix}__footer`} part="footer">
                <slot name="footer"></slot>
              </div>
            )}
          </div>
        </div>
      </Host>
    );
  }
}
